1	#!/usr/bin/env node
2	/**
3	 * Common Ground (ch13) journey probe — v2 of cg-lifecycle-probe.mjs, run-local
4	 * to 2026-09-05-after-the-hearth. The v1 probe is left untouched so the
5	 * pre-repair captures keep their exact generator.
6	 *
7	 * Adds, over v1:
8	 *   - ROOT CHECKPOINT CONTROL. verifier-control.json is re-read every
9	 *     `--control-ms` (default 10 s, always < the 45 s coordination bound). When
10	 *     root sets action `finish-current-and-checkpoint` (or `pause`/`stop`) the
11	 *     loop stops at the next sample, still writes every frame, the trace and a
12	 *     complete summary, and exits 0 with `checkpointed: true` plus the control
13	 *     record that stopped it. Nothing is left half-written.
14	 *   - PHYSICAL TRAVERSAL MEASUREMENT. Player pose (`__autopilot.pos`) and the
15	 *     audit worker's pose (`__auditWorker`) are integrated into an actual walked
16	 *     path length, with per-sample poses in the trace, a 1 Hz pose ledger, net
17	 *     displacement, and the ordered list of distinct positions. This measures
18	 *     real bodies, not the controller's own opinion of its progress.
19	 *   - RETARGET / SHORTCUT DETECTION. Records every time the walked path turns
20	 *     back toward a previously visited position (backtrack episodes) and the
21	 *     largest single-sample jump (teleport candidate).
22	 *   - STALL DETECTION. Longest window with no beat/objective/anchor/milestone
23	 *     change AND player displacement under `--stall-units`.
24	 *   - STOP PREDICATES: --until-beat, --until-anchor, --until-objective,
25	 *     --until-objective-clear, --until-milestone. Reaching one records
26	 *     `stopReason` and the elapsed time; not reaching one is a measured failure,
27	 *     never a rescue.
28	 *   - Optional HUD-suppressed perceptual frame beside each raw frame
29	 *     (`--percept`), so UX evidence and perceptual evidence stay distinct.
30	 *
31	 * It asserts nothing about taste, and grants nothing to the runtime: every
32	 * page interaction is read-only except explicitly requested key input.
33	 *
34	 *   node cg-journey-probe.mjs --beat ch13-home --lane movie --seconds 240 \
35	 *        --until-beat ch13-return --strip-s 5 --out post/home-movie-1
36	 */
37	import { mkdirSync, writeFileSync, appendFileSync, readFileSync } from 'node:fs';
38	import { resolve, join, dirname } from 'node:path';
39	import { createHash } from 'node:crypto';
40	import process from 'node:process';
41	import {
42	  loadContract, objectiveExpectations, anchorsByBeat, contingentAnchorIds,
43	  ART, CAPTURES, RUN_DIR
44	} from './lib/cgContract.mjs';
45	import {
46	  openParavoxia, waitReady, readState, frameStats, hideUi, showUi,
47	  SWIFTSHADER, CAPTURE_TIER
48	} from '../../../../../main/tools/lib/evidence.mjs';
49	
50	const arg = (name, fallback = null) => {
51	  const i = process.argv.indexOf(`--${name}`);
52	  return i >= 0 && process.argv[i + 1] !== undefined && !process.argv[i + 1].startsWith('--')
53	    ? process.argv[i + 1] : fallback;
54	};
55	const has = (n) => process.argv.includes(`--${n}`);
56	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
57	const tag = (m) => console.log(`[cg-journey] ${m}`);
58	
59	const beat = arg('beat', 'ch13-home');
60	const lane = arg('lane', 'movie');
61	const seconds = Number(arg('seconds', '180'));
62	const variant = arg('variant', 'desktop');
63	const tier = arg('tier', null);
64	const outName = arg('out', `${beat}-${lane}-${variant}`);
65	const sampleMs = Number(arg('sample-ms', '100'));
66	const stripS = Number(arg('strip-s', '0'));
67	const extraQuery = arg('query', '');
68	const noShots = has('no-shots');
69	const percept = has('percept');
70	const controlMs = Number(arg('control-ms', '10000'));
71	const stallUnits = Number(arg('stall-units', '0.75'));
72	const untilBeat = arg('until-beat', null);
73	const untilAnchor = arg('until-anchor', null);
74	const untilObjective = arg('until-objective', null);
75	const untilObjectiveClear = arg('until-objective-clear', null);
76	const untilMilestone = arg('until-milestone', null);
77	const holdAfterMs = Number(arg('hold-after-ms', '0'));
78	
79	const CONTROL_PATH = resolve(RUN_DIR, 'verifier-control.json');
80	const CHECKPOINT_ACTIONS = new Set(['finish-current-and-checkpoint', 'pause', 'stop', 'halt']);
81	
82	// --------------------------------------------------------- self-test -------
83	// Exercises the checkpoint decision and the traversal math with no preview, no
84	// browser and no game source. Run before every measurement session.
85	if (has('self-test')) {
86	  const fail = (m) => { console.error(`[cg-journey self-test] FAIL ${m}`); process.exit(1); };
87	  const CHK = new Set(['finish-current-and-checkpoint', 'pause', 'stop', 'halt']);
88	  for (const a of ['finish-current-and-checkpoint', 'pause', 'stop', 'halt']) if (!CHK.has(a)) fail(`action ${a} not a checkpoint`);
89	  for (const a of ['continue', 'go', '', undefined]) if (CHK.has(String(a))) fail(`action ${a} wrongly a checkpoint`);
90	  const live = JSON.parse(readFileSync(CONTROL_PATH, 'utf8'));
91	  if (typeof live.action !== 'string') fail('live verifier-control.json has no action');
92	  const t = { name: 't', first: null, last: null, path: 0, path2d: 0, maxJump: 0, maxJumpAtMs: null, poses: [], samples: 0, backtracks: [], farthestFromFirst: 0 };
93	  const trk = (pos, at) => { // mirrors track()
94	    if (!Array.isArray(pos)) return;
95	    t.samples += 1;
96	    if (!t.first) { t.first = [...pos]; t.last = [...pos]; t.poses.push({ atMs: at, pos: [...pos] }); return; }
97	    const d = Math.hypot(pos[0] - t.last[0], pos[1] - t.last[1], pos[2] - t.last[2]);
98	    if (d > t.maxJump) { t.maxJump = d; }
99	    t.path += d;
100	    const ff = Math.hypot(pos[0] - t.first[0], pos[1] - t.first[1], pos[2] - t.first[2]);
101	    if (ff > t.farthestFromFirst) t.farthestFromFirst = ff;
102	    if (t.farthestFromFirst - ff > 1.5) t.backtracks.push({ at });
103	    t.last = [...pos];
104	  };
105	  // an L walk: 10 units +x, then 8 units +z => path 18, net hypot(10,8)=12.806
106	  for (let i = 0; i <= 10; i += 1) trk([i, 0, 0], i);
107	  for (let i = 1; i <= 8; i += 1) trk([10, 0, i], 10 + i);
108	  if (Math.abs(t.path - 18) > 1e-6) fail(`L-walk path ${t.path} != 18`);
109	  const net = Math.hypot(10, 0, 8);
110	  if (Math.abs(net - 12.8062) > 1e-3) fail('net displacement math');
111	  if (t.backtracks.length !== 0) fail('forward L-walk reported a backtrack');
112	  // a retarget-to-start regression: walk out 6 then return to origin
113	  for (let i = 5; i >= 0; i -= 1) trk([10, 0, i], 20 + (5 - i));
114	  if (t.backtracks.length === 0) fail('return toward start not detected as backtrack');
115	  console.log('[cg-journey self-test] OK — checkpoint actions, L-walk path=18.000, net=12.806, backtrack detection');
116	  process.exit(0);
117	}
118	
119	const ownership = JSON.parse(readFileSync(resolve(ART, 'preview-ownership.json'), 'utf8'));
120	if (ownership.state !== 'running') {
121	  throw new Error(`owned preview is "${ownership.state}", not running — refusing to measure or to start one`);
122	}
123	const baseUrl = ownership.url;
124	
125	const { contract, sha256: contractSha } = loadContract();
126	const expectations = objectiveExpectations(contract);
127	const beatAnchors = anchorsByBeat(contract).get(beat) ?? [];
128	const contingent = new Set(contingentAnchorIds(contract));
129	
130	const outDir = resolve(CAPTURES, outName);
131	mkdirSync(outDir, { recursive: true });
132	const tracePath = join(outDir, 'trace.ndjson');
133	writeFileSync(tracePath, '');
134	const frames = [];
135	const events = [];
136	
137	const viewport = variant === 'mobile' ? { width: 390, height: 844 } : { width: 1280, height: 720 };
138	const query = new URLSearchParams({ story: beat, journeyprobe: '1', debug: '1' });
139	if (lane === 'movie') query.set('movie', '1');
140	if (tier) query.set('quality', tier);
141	for (const kv of extraQuery.split('&').filter(Boolean)) {
142	  const [k, v = '1'] = kv.split('=');
143	  query.set(k, v);
144	}
145	const url = `?${query.toString()}`;
146	
147	tag(`beat=${beat} lane=${lane} variant=${variant}${tier ? ` tier=${tier}` : ''} url=${baseUrl}${url}`);
148	
149	// ------------------------------------------------------------ control -------
150	let lastControlCheck = 0;
151	let controlStop = null;
152	let lastControlSeen = null;
153	function pollControl(force = false) {
154	  if (!force && Date.now() - lastControlCheck < controlMs) return null;
155	  lastControlCheck = Date.now();
156	  try {
157	    const raw = JSON.parse(readFileSync(CONTROL_PATH, 'utf8'));
158	    const sig = JSON.stringify(raw);
159	    if (sig !== lastControlSeen) {
160	      lastControlSeen = sig;
161	      appendFileSync(tracePath, `${JSON.stringify({ kind: 'control', atMs: Date.now(), control: raw })}\n`);
162	      tag(`control action=${raw.action} updatedAt=${raw.updatedAt}`);
163	    }
164	    if (CHECKPOINT_ACTIONS.has(String(raw.action))) { controlStop = raw; return raw; }
165	  } catch (e) {
166	    appendFileSync(tracePath, `${JSON.stringify({ kind: 'control-error', atMs: Date.now(), error: String(e).slice(0, 200) })}\n`);
167	  }
168	  return null;
169	}
170	pollControl(true);
171	if (controlStop) {
172	  tag(`root control is "${controlStop.action}" before the browser opened — not measuring`);
173	  writeFileSync(join(outDir, 'summary.json'), `${JSON.stringify({
174	    schema: 'paravoxia.verifier.cgJourneyProbe.v1', probe: 'cg-journey-probe.mjs',
175	    checkpointed: true, ranBrowser: false, control: controlStop,
176	    request: { beat, lane, variant, tier, seconds }
177	  }, null, 2)}\n`);
178	  process.exit(0);
179	}
180	
181	// ------------------------------------------------------------ session -------
182	const session = await openParavoxia({
183	  url,
184	  preview: { url: baseUrl, stop() {} },
185	  build: false,
186	  viewport,
187	  isMobile: variant === 'mobile',
188	  reducedMotion: variant === 'reduced-motion' ? 'reduce' : 'no-preference',
189	  log: tag
190	});
191	const { page } = session;
192	await waitReady(page, { timeoutMs: 180_000 });
193	
194	async function sample() {
195	  const base = await readState(page);
196	  const extra = await page.evaluate(() => {
197	    const out = {};
198	    try {
199	      const s = window.__paravoxiaJourneyProbe?.getSnapshot?.();
200	      if (s) {
201	        out.objectiveFull = s.objective ?? null;
202	        out.avFull = s.state?.signedSceneAv ?? null;
203	        out.receipts = s.receipts ?? null;
204	        out.entities = Array.isArray(s.entities)
205	          ? s.entities.map((e) => ({ id: e.id, kind: e.kind ?? null, pos: e.position ?? e.pos ?? null }))
206	          : null;
207	        out.prompts = s.interaction?.prompts ?? null;
208	        out.visiblePromptCount = s.interaction?.visiblePromptCount ?? null;
209	        out.interactionTrace = (s.interaction?.trace?.entries ?? []).slice(-6);
210	        out.interactionResolution = s.interaction?.resolution ?? null;
211	        out.input = s.input ? { keys: s.input.keys ?? null, mode: s.input.mode ?? null } : null;
212	        out.localActor = s.state?.localActor
213	          ? { id: s.state.localActor.id ?? null, milestones: s.state.localActor.milestones ?? null }
214	          : null;
215	      }
216	    } catch (e) { out.snapshotError = String(e).slice(0, 160); }
217	    try {
218	      const lc = window.__voxObjectiveLifecycle?.();
219	      if (lc) { out.objectiveLifecycleTrace = lc.map((e) => ({ ...e })); out.objectiveLifecycleCount = lc.length; }
220	    } catch { /* read-only */ }
221	    try {
222	      const t = window.__voxSfxTrace?.();
223	      if (t) {
224	        out.sfxTriggerCounts = t.triggerCounts ?? null;
225	        out.sfxRecent = (t.events ?? []).slice(-8);
226	        out.sfxTotal = (t.events ?? []).length;
227	      }
228	    } catch { /* read-only */ }
229	    try { out.auditWorker = window.__auditWorker ? { ...window.__auditWorker } : null; } catch { out.auditWorker = null; }
230	    try {
231	      const hud = document.querySelector('[data-story-guidance-hud]');
232	      out.hud = hud ? {
233	        objectiveId: hud.getAttribute('data-objective-id'),
234	        markerLabel: hud.getAttribute('data-objective-marker-label'),
235	        health: hud.getAttribute('data-objective-health'),
236	        requiresMarker: hud.getAttribute('data-objective-requires-marker'),
237	        lines: [...hud.querySelectorAll('li, p, span')].map((n) => n.textContent.trim()).filter(Boolean)
238	      } : null;
239	    } catch { /* read-only */ }
240	    try {
241	      out.markerCount = document.querySelectorAll('[data-objective-marker], [data-story-marker]').length;
242	    } catch { /* read-only */ }
243	    return out;
244	  });
245	  return { ...base, ...extra, tMs: Date.now() };
246	}
247	
248	// Perceptual (HUD-suppressed) twins are expensive (hide + 2 shots + show) and
249	// were observed to starve the 10 Hz state sampler during dense event bursts, so
250	// they are paired only with coverage-strip and anchor frames. Event frames stay
251	// raw HUD-inclusive, which is the evidence class UX review needs anyway.
252	async function shoot(label, { perceptPair = percept && /^(strip|anchor|after-anchor|stop|hold-after)/.test(label) } = {}) {
253	  if (noShots) return null;
254	  const idx = String(frames.length).padStart(4, '0');
255	  const safe = label.replace(/[^\w.-]+/g, '_');
256	  const file = join(outDir, `${idx}-${safe}.png`);
257	  const bytes = await page.screenshot({ path: file });
258	  const rec = {
259	    file, label, kind: 'raw-hud-inclusive',
260	    sha256: createHash('sha256').update(bytes).digest('hex'),
261	    bytes: bytes.length, stats: frameStats(bytes), atMs: Date.now(),
262	    beat: lastSampledBeat, objectiveId: lastSampledObjective, anchor: lastSampledAnchor
263	  };
264	  frames.push(rec);
265	  if (perceptPair) {
266	    try {
267	      await hideUi(page);
268	      const pfile = join(outDir, `${idx}-${safe}.percept.png`);
269	      const pbytes = await page.screenshot({ path: pfile });
270	      frames.push({
271	        file: pfile, label: `${label} (hud-suppressed)`, kind: 'perceptual-hud-suppressed',
272	        sha256: createHash('sha256').update(pbytes).digest('hex'),
273	        bytes: pbytes.length, stats: frameStats(pbytes), atMs: Date.now(),
274	        beat: lastSampledBeat, objectiveId: lastSampledObjective, anchor: lastSampledAnchor,
275	        pairedWith: file
276	      });
277	    } finally { await showUi(page); }
278	  }
279	  return rec;
280	}
281	
282	// ------------------------------------------------------- traversal math -----
283	const dist = (a, b) => (Array.isArray(a) && Array.isArray(b) && a.length >= 3 && b.length >= 3)
284	  ? Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]) : null;
285	const dist2d = (a, b) => (Array.isArray(a) && Array.isArray(b) && a.length >= 3 && b.length >= 3)
286	  ? Math.hypot(a[0] - b[0], a[2] - b[2]) : null;
287	
288	function makeTracker(name) {
289	  return {
290	    name, first: null, last: null, path: 0, path2d: 0, maxJump: 0, maxJumpAtMs: null,
291	    poses: [], samples: 0, backtracks: [], farthestFromFirst: 0
292	  };
293	}
294	function track(t, pos, atMs) {
295	  if (!Array.isArray(pos) || pos.length < 3 || pos.some((n) => typeof n !== 'number' || !Number.isFinite(n))) return;
296	  t.samples += 1;
297	  if (!t.first) { t.first = [...pos]; t.last = [...pos]; t.poses.push({ atMs, pos: [...pos] }); return; }
298	  const d = dist(t.last, pos);
299	  const d2 = dist2d(t.last, pos);
300	  if (d === null) return;
301	  if (d > t.maxJump) { t.maxJump = d; t.maxJumpAtMs = atMs; }
302	  t.path += d;
303	  t.path2d += d2 ?? 0;
304	  const fromFirst = dist(t.first, pos);
305	  if (fromFirst > t.farthestFromFirst) t.farthestFromFirst = fromFirst;
306	  // Backtrack: moving materially closer to the start after having been farther.
307	  if (t.farthestFromFirst - fromFirst > 1.5) {
308	    const lastBt = t.backtracks[t.backtracks.length - 1];
309	    if (!lastBt || atMs - lastBt.lastAtMs > 2000) {
310	      t.backtracks.push({ startedAtMs: atMs, lastAtMs: atMs, farthestFromFirst: t.farthestFromFirst, nowFromFirst: fromFirst });
311	    } else { lastBt.lastAtMs = atMs; lastBt.nowFromFirst = fromFirst; }
312	  }
313	  if (d > 0.05 || atMs - (t.poses[t.poses.length - 1]?.atMs ?? 0) > 1000) t.poses.push({ atMs, pos: [...pos] });
314	  t.last = [...pos];
315	}
316	function summarizeTracker(t) {
317	  return {
318	    name: t.name, samplesWithPose: t.samples,
319	    firstPos: t.first, lastPos: t.last,
320	    walkedPathUnits: Math.round(t.path * 1000) / 1000,
321	    walkedPathUnitsHorizontal: Math.round(t.path2d * 1000) / 1000,
322	    netDisplacementUnits: t.first && t.last ? Math.round(dist(t.first, t.last) * 1000) / 1000 : null,
323	    farthestFromStartUnits: Math.round(t.farthestFromFirst * 1000) / 1000,
324	    largestSingleSampleJumpUnits: Math.round(t.maxJump * 1000) / 1000,
325	    largestJumpAtMs: t.maxJumpAtMs,
326	    backtrackEpisodes: t.backtracks,
327	    poseLedgerCount: t.poses.length
328	  };
329	}
330	const player = makeTracker('player');
331	const worker = makeTracker('audit-worker');
332	
333	// ------------------------------------------------------------- main loop ----
334	// ---------------------------------------------- labelled prerequisite fixture
335	// `--prereq-exit-ship` presses the SHIPPED ordinary disembark key (F, the same
336	// handler a player uses: App.tsx binds KeyF while surface+flight) exactly once,
337	// only if the entry actually booted aboard the ship. It is a PREREQUISITE
338	// FIXTURE, recorded as such: it is not part of any cold-journey claim, it grants
339	// no milestone, progress, position or route credit, and it is refused if the
340	// entry was already on foot.
341	const prerequisiteFixtures = [];
342	if (has('prereq-exit-ship')) {
343	  const before = await sample();
344	  const aboard = before.spaceFlight?.controlMode === 'flight' && before.spaceFlight?.phase === 'surface';
345	  const rec = {
346	    type: 'ordinary-disembark',
347	    labelled: 'PREREQUISITE FIXTURE — not evidence of any journey, passage or beat entry',
348	    input: 'KeyF (the shipped surface+flight exit handler in App.tsx)',
349	    grantsProgress: false,
350	    appliedAt: new Date().toISOString(),
351	    stateBefore: { spaceFlight: before.spaceFlight ?? null, pos: before.autopilot?.pos ?? null, beat: before.beat ?? null },
352	    applied: false, stateAfter: null, refusedReason: null
353	  };
354	  if (!aboard) {
355	    rec.refusedReason = 'entry was not surface+flight — no disembark was needed or performed';
356	  } else {
357	    await page.keyboard.press('KeyF');
358	    await sleep(700);
359	    const after = await sample();
360	    rec.applied = true;
361	    rec.stateAfter = { spaceFlight: after.spaceFlight ?? null, pos: after.autopilot?.pos ?? null, beat: after.beat ?? null };
362	    rec.controlModeChanged = before.spaceFlight?.controlMode !== after.spaceFlight?.controlMode;
363	  }
364	  prerequisiteFixtures.push(rec);
365	  appendFileSync(tracePath, `${JSON.stringify({ kind: 'prerequisite-fixture', atMs: Date.now(), fixture: rec })}\n`);
366	  tag(`prerequisite-fixture ${JSON.stringify(rec).slice(0, 300)}`);
367	}
368	
369	const started = Date.now();
370	let last = null;
371	let lastAnchor = null;
372	let lastStrip = 0;
373	let pendingAfterShot = null;
374	let lastSampledBeat = null;
375	let lastSampledObjective = null;
376	let lastSampledAnchor = null;
377	let stopReason = null;
378	let stopAtMs = null;
379	const objectiveEntries = [];
380	const anchorLedger = [];
381	const beatLedger = [];
382	const milestoneLedger = [];
383	let lastChangeAtMs = started;
384	let lastChangePos = null;
385	let longestStall = { ms: 0, fromMs: null, toMs: null, beat: null, objectiveId: null, playerMovedUnits: null };
386	let stallAccumUnits = 0;
387	
388	function noteEvent(type, payload) {
389	  const rec = { type, atMs: Date.now(), elapsedMs: Date.now() - started, ...payload };
390	  events.push(rec);
391	  appendFileSync(tracePath, `${JSON.stringify({ kind: 'event', ...rec })}\n`);
392	  tag(`${type} ${JSON.stringify(payload).slice(0, 240)}`);
393	  return rec;
394	}
395	function markChange(now, s) {
396	  const stalled = now - lastChangeAtMs;
397	  if (stalled > longestStall.ms && stallAccumUnits < stallUnits) {
398	    longestStall = {
399	      ms: stalled, fromMs: lastChangeAtMs, toMs: now,
400	      beat: s?.beat ?? null, objectiveId: s?.hud?.objectiveId ?? null,
401	      playerMovedUnits: Math.round(stallAccumUnits * 1000) / 1000
402	    };
403	  }
404	  lastChangeAtMs = now;
405	  stallAccumUnits = 0;
406	  lastChangePos = null;
407	}
408	
409	while (Date.now() - started < seconds * 1000) {
410	  const s = await sample();
411	  const now = Date.now();
412	  appendFileSync(tracePath, `${JSON.stringify({ kind: 'sample', elapsedMs: now - started, s })}\n`);
413	
414	  const objId = s.hud?.objectiveId ?? s.objectiveId ?? null;
415	  const label = s.hud?.markerLabel ?? s.markerLabel ?? null;
416	  const workOrder = s.objectiveFull?.workOrder ?? null;
417	  const anchor = s.avFull?.anchorId ?? null;
418	  const sfxEnter = s.sfxTriggerCounts?.objectiveEnter ?? 0;
419	  const playerPos = s.autopilot?.pos ?? null;
420	  const workerPos = s.auditWorker?.pos ?? null;
421	  const milestones = s.localActor?.milestones ?? s.milestones ?? null;
422	  lastSampledBeat = s.beat ?? null;
423	  lastSampledObjective = objId;
424	  lastSampledAnchor = anchor;
425	
426	  const prevPlayerLast = player.last ? [...player.last] : null;
427	  track(player, playerPos, now);
428	  track(worker, workerPos, now);
429	  if (prevPlayerLast && player.last) stallAccumUnits += dist(prevPlayerLast, player.last) ?? 0;
430	
431	  if (pendingAfterShot && now >= pendingAfterShot.at) {
432	    await shoot(`after-${pendingAfterShot.label}`);
433	    pendingAfterShot = null;
434	  }
435	
436	  if (!last || last.beat !== (s.beat ?? null)) {
437	    if (last) noteEvent('beat-change', { from: last.beat, to: s.beat ?? null });
438	    beatLedger.push({ beat: s.beat ?? null, atMs: now, elapsedMs: now - started, objectiveId: objId, anchor });
439	    if (last) { await shoot(`beat-${s.beat ?? 'none'}`); markChange(now, s); }
440	  }
441	
442	  if (!last || last.objId !== objId) {
443	    if (last?.objId) noteEvent('objective-clear', { objectiveId: last.objId, beat: s.beat, anchor });
444	    if (objId) {
445	      const exp = expectations.get(objId) ?? null;
446	      objectiveEntries.push({
447	        objectiveId: objId, atMs: now, elapsedMs: now - started,
448	        beat: s.beat, enterAnchor: anchor, markerLabel: label, workOrder,
449	        health: s.hud?.health ?? null, requiresMarker: s.hud?.requiresMarker ?? null,
450	        markerCountAtEntry: s.markerCount ?? null,
451	        sfxObjectiveEnterAtEntry: sfxEnter,
452	        expectedMarkerLabel: exp?.markerLabel ?? null,
453	        expectedWorkOrder: exp?.workOrder ?? null,
454	        conditionalWorkOrders: exp?.conditionalWorkOrders ?? [],
455	        markerLabelMatchesSigned: exp ? label === exp.markerLabel : null,
456	        playerPosAtEntry: playerPos, workerPosAtEntry: workerPos,
457	        textStates: []
458	      });
459	      noteEvent('objective-enter', { objectiveId: objId, markerLabel: label, workOrder, anchor, health: s.hud?.health ?? null });
460	      await shoot(`obj-enter-${objId}`);
461	    }
462	    markChange(now, s);
463	  } else if (objId && JSON.stringify(last.workOrder) !== JSON.stringify(workOrder)) {
464	    const entry = objectiveEntries[objectiveEntries.length - 1];
465	    entry?.textStates.push({
466	      atMs: now, elapsedMs: now - started, from: last.workOrder, to: workOrder,
467	      markerLabelBefore: last.label, markerLabelAfter: label, anchor,
468	      sfxObjectiveEnterCount: sfxEnter, healthAfter: s.hud?.health ?? null,
469	      playerPos, workerPos
470	    });
471	    noteEvent('objective-text-change', { objectiveId: objId, to: workOrder, markerLabel: label, anchor, sfxEnterCount: sfxEnter });
472	    await shoot(`obj-text-${objId}`);
473	    markChange(now, s);
474	  } else if (objId && last.label !== label) {
475	    noteEvent('objective-marker-label-change', { objectiveId: objId, from: last.label, to: label });
476	    markChange(now, s);
477	  }
478	
479	  if (anchor !== lastAnchor) {
480	    await shoot(`anchor-${anchor ?? 'none'}`);
481	    anchorLedger.push({
482	      anchorId: anchor, atMs: now, elapsedMs: now - started,
483	      event: s.avFull?.anchorEvent ?? null, sequence: s.avFull?.activationSequence ?? null,
484	      beat: s.beat, objectiveId: objId, contingent: contingent.has(anchor),
485	      playerPos, workerPos
486	    });
487	    noteEvent('anchor-change', { from: lastAnchor, to: anchor, sequence: s.avFull?.activationSequence ?? null });
488	    pendingAfterShot = { label: `anchor-${anchor ?? 'none'}`, at: now + 1200 };
489	    lastAnchor = anchor;
490	    markChange(now, s);
491	  }
492	
493	  const msSig = JSON.stringify(milestones ?? null);
494	  if (!last || last.msSig !== msSig) {
495	    if (last) {
496	      milestoneLedger.push({ atMs: now, elapsedMs: now - started, beat: s.beat, milestones });
497	      noteEvent('milestone-change', { beat: s.beat, milestones });
498	      markChange(now, s);
499	    } else milestoneLedger.push({ atMs: now, elapsedMs: now - started, beat: s.beat, milestones, initial: true });
500	  }
501	
502	  if (stripS > 0 && now - lastStrip >= stripS * 1000) {
503	    lastStrip = now;
504	    await shoot(`strip-${s.beat ?? 'none'}`);
505	  }
506	
507	  last = { objId, label, workOrder, anchor, beat: s.beat ?? null, msSig };
508	
509	  // stop predicates
510	  if (untilBeat && s.beat === untilBeat) { stopReason = `reached-beat:${untilBeat}`; stopAtMs = now; }
511	  if (untilAnchor && anchor === untilAnchor) { stopReason = `reached-anchor:${untilAnchor}`; stopAtMs = now; }
512	  if (untilObjective && objId === untilObjective) { stopReason = `reached-objective:${untilObjective}`; stopAtMs = now; }
513	  if (untilObjectiveClear && events.some((e) => e.type === 'objective-clear' && e.objectiveId === untilObjectiveClear)) {
514	    stopReason = `cleared-objective:${untilObjectiveClear}`; stopAtMs = now;
515	  }
516	  if (untilMilestone && msSig && msSig.includes(untilMilestone)) { stopReason = `milestone:${untilMilestone}`; stopAtMs = now; }
517	  if (stopReason) {
518	    noteEvent('stop-predicate', { stopReason, elapsedMs: now - started });
519	    await shoot(`stop-${stopReason.replace(/[^\w.-]+/g, '_')}`);
520	    if (holdAfterMs > 0) {
521	      const holdEnd = Date.now() + holdAfterMs;
522	      while (Date.now() < holdEnd) {
523	        const hs = await sample();
524	        appendFileSync(tracePath, `${JSON.stringify({ kind: 'hold-sample', elapsedMs: Date.now() - started, s: hs })}\n`);
525	        track(player, hs.autopilot?.pos ?? null, Date.now());
526	        track(worker, hs.auditWorker?.pos ?? null, Date.now());
527	        await sleep(sampleMs);
528	      }
529	      await shoot(`hold-after-${stopReason.replace(/[^\w.-]+/g, '_')}`);
530	    }
531	    break;
532	  }
533	
534	  if (pollControl()) {
535	    noteEvent('root-checkpoint', { action: controlStop.action, updatedAt: controlStop.updatedAt });
536	    await shoot('root-checkpoint');
537	    break;
538	  }
539	
540	  await sleep(sampleMs);
541	}
542	
543	markChange(Date.now(), last ? { beat: last.beat, hud: { objectiveId: last.objId } } : null);
544	const finalState = await sample();
545	const endedAt = Date.now();
546	
547	const summary = {
548	  schema: 'paravoxia.verifier.cgJourneyProbe.v1',
549	  runId: '2026-09-05-after-the-hearth',
550	  probe: 'cg-journey-probe.mjs',
551	  probeSha256: createHash('sha256').update(readFileSync(new URL(import.meta.url))).digest('hex'),
552	  contractSha256: contractSha,
553	  preview: { url: baseUrl, indexSha256: ownership.indexSha256, buildHash: ownership.buildHash ?? null, ownershipState: ownership.state },
554	  renderer: session.renderer,
555	  rendererClass: /swiftshader|software|llvmpipe|swangle/i.test(String(session.renderer)) ? 'software' : 'hardware',
556	  headed: session.headed,
557	  captureTier: CAPTURE_TIER,
558	  swiftshaderAllowed: SWIFTSHADER,
559	  prerequisiteFixtures,
560	  prerequisiteFixtureNote: 'Any fixture listed here is explicitly labelled setup performed through shipped player input. A run containing a fixture is NOT a cold no-rescue journey and is never reported as one.',
561	  request: {
562	    beat, lane, variant, tier, seconds, url: `${baseUrl}${url}`, viewport,
563	    stopPredicates: { untilBeat, untilAnchor, untilObjective, untilObjectiveClear, untilMilestone }
564	  },
565	  startedAt: new Date(started).toISOString(),
566	  endedAt: new Date(endedAt).toISOString(),
567	  elapsedMs: endedAt - started,
568	  stopReason: stopReason ?? (controlStop ? 'root-checkpoint' : 'seconds-budget-exhausted'),
569	  stopElapsedMs: stopAtMs ? stopAtMs - started : null,
570	  checkpointed: Boolean(controlStop),
571	  control: controlStop ?? null,
572	  beatAnchorsExpected: beatAnchors.map((a) => ({ id: a.id, order: a.order, contingent: contingent.has(a.id) })),
573	  beatLedger,
574	  anchorLedger,
575	  objectiveEntries,
576	  milestoneLedger,
577	  traversal: {
578	    player: summarizeTracker(player),
579	    auditWorker: summarizeTracker(worker),
580	    note: 'Walked path is integrated from actual sampled body poses at the probe sample rate; it is a lower bound on true path length and is independent of any runtime progress counter.'
581	  },
582	  stall: {
583	    longest: longestStall,
584	    thresholdUnits: stallUnits,
585	    note: 'A stall window is time with no beat/objective/anchor/milestone change AND player displacement under the threshold. A stall is a failure to report, not a rescue.'
586	  },
587	  playerPoseLedger: player.poses,
588	  workerPoseLedger: worker.poses,
589	  events,
590	  frames,
591	  objectiveLifecycleTrace: finalState.objectiveLifecycleTrace ?? null,
592	  finalState: {
593	    beat: finalState.beat,
594	    objectiveId: finalState.hud?.objectiveId ?? null,
595	    markerLabel: finalState.hud?.markerLabel ?? null,
596	    health: finalState.hud?.health ?? null,
597	    workOrder: finalState.objectiveFull?.workOrder ?? null,
598	    milestones: finalState.localActor?.milestones ?? finalState.milestones ?? null,
599	    anchor: finalState.avFull?.anchorId ?? null,
600	    autopilot: finalState.autopilot ?? null,
601	    auditWorker: finalState.auditWorker ?? null,
602	    prompts: finalState.interactionPrompts ?? null
603	  },
604	  pageErrors: session.pageErrors.slice(0, 20),
605	  sfxNote: 'objectiveEnter counts are runtime SFX queue observations; they are not an audibility or hearing claim.'
606	};
607	writeFileSync(join(outDir, 'summary.json'), `${JSON.stringify(summary, null, 2)}\n`);
608	tag(`wrote ${join(outDir, 'summary.json')} (${frames.length} frames, ${events.length} events, stop=${summary.stopReason})`);
609	await session.stop();
