  if (forward.lengthSq() > 1e-9) _forward.copy(forward).normalize();
  _pitch = pitch;
}

export function getPlayerLook(): { forward: THREE.Vector3; pitch: number } {
  return { forward: _forward.clone(), pitch: _pitch };
}

