async function shoot(label, { perceptPair = percept && /^(strip|anchor|after-anchor|stop|hold-after)/.test(label) } = {}) {
  if (noShots) return null;
  const idx = String(frames.length).padStart(4, '0');
  const safe = label.replace(/[^\w.-]+/g, '_');
  const file = join(outDir, `${idx}-${safe}.png`);
  const bytes = await page.screenshot({ path: file });
  const rec = {
    file, label, kind: 'raw-hud-inclusive',
    sha256: createHash('sha256').update(bytes).digest('hex'),
    bytes: bytes.length, stats: frameStats(bytes), atMs: Date.now(),
    beat: lastSampledBeat, objectiveId: lastSampledObjective, anchor: lastSampledAnchor
  };
  frames.push(rec);
  if (perceptPair) {
    try {
      await hideUi(page);
      const pfile = join(outDir, `${idx}-${safe}.percept.png`);
      const pbytes = await page.screenshot({ path: pfile });
      frames.push({
        file: pfile, label: `${label} (hud-suppressed)`, kind: 'perceptual-hud-suppressed',
        sha256: createHash('sha256').update(pbytes).digest('hex'),
        bytes: pbytes.length, stats: frameStats(pbytes), atMs: Date.now(),
        beat: lastSampledBeat, objectiveId: lastSampledObjective, anchor: lastSampledAnchor,
        pairedWith: file
      });
    } finally { await showUi(page); }
  }
  return rec;
}

