writeFileSync(join(outDir, 'summary.json'), `${JSON.stringify(summary, null, 2)}\n`);
tag(`wrote ${join(outDir, 'summary.json')} (${frames.length} frames, ${events.length} events, stop=${summary.stopReason})`);
await session.stop();

