}

/** The minimal per-frame observation used for capture provenance. */
const provObs = (s, atMs) => observation({
  beat: s?.beat ?? null,
  objectiveId: s?.hud?.objectiveId ?? s?.objectiveId ?? null,
  markerLabel: s?.hud?.markerLabel ?? s?.markerLabel ?? null,
