  appendFileSync(tracePath, `${JSON.stringify({ kind: 'prerequisite-fixture', atMs: Date.now(), fixture: rec })}\n`);
  tag(`prerequisite-fixture ${JSON.stringify(rec).slice(0, 300)}`);
