const started = Date.now();
let last = null;
let lastAnchor = null;
let lastStrip = 0;
let pendingAfterShot = null;
let lastSampledBeat = null;
let lastSampledObjective = null;
let lastSampledAnchor = null;
let stopReason = null;
let stopAtMs = null;
