    tag(`pose-source player=${s.playerPose?.source ?? 'none'} worker=${s.workerPose?.source ?? 'none'} cgDiag=${s.cgDiagnostic?.available ? s.cgDiagnostic.hookUsed : 'UNAVAILABLE'}`);
