await session.stop();
// Media and trace are fully finalized above before any non-zero exit. A stall
// FAIL exits 3 so a batch runner stops early; a root checkpoint still exits 0.
if (stallFailure) {
  tag(`FAIL-STALL after ${stallFailure.windowMs} ms with no observable change — captured and finalized, no rescue attempted`);
  process.exit(3);
}

