    try { out.beat = window.__storyBeat ?? null; } catch { /* read-only */ }
    try { out.playerPos = window.__autopilot?.pos ?? null; } catch { /* read-only */ }
    try { out.workerPos = window.__auditWorker?.pos ?? null; } catch { /* read-only */ }
    try {
